"""Retain synchronized Native turn-signal sources for saved processing.

The recorder accepts only camera images and actor state from the same CARLA
snapshot. It creates no derived observation channels or synthetic video.
"""

import json
import math
import subprocess
from contextlib import ExitStack, contextmanager
from pathlib import Path
from queue import Empty


CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")
SIZES = {"overview": (1920, 1080), "approach": (1280, 720),
         "reference_corner": (1280, 720), "driver_reference": (1280, 720)}
RATE_HZ = 20


def _finite(value):
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError("Nonfinite Native source value")
    return float(value)


def source_camera_frame(queue, expected_frame):
    if type(expected_frame) is not int or expected_frame < 0:
        raise ValueError("Nonnegative Native frame required")
    for _ in range(8):
        try:
            image = queue.get(timeout=10)
        except Empty as error:
            raise ValueError("Original camera frame missing") from error
        if image.frame == expected_frame:
            return bytes(image.raw_data)
        if image.frame > expected_frame:
            raise ValueError("Original camera skipped Native frame")
    raise ValueError("Original camera frame join failed")


def source_row(snapshot, actor, carla, waypoint=None):
    frame = snapshot.frame
    time_s = snapshot.timestamp.elapsed_seconds
    if type(frame) is not int or frame < 0:
        raise ValueError("Invalid Native snapshot frame")
    position = actor.get_location()
    velocity = actor.get_velocity()
    heading = actor.get_transform().rotation.yaw
    state = actor.get_light_state()
    row = {"frame": frame, "time_s": _finite(time_s),
            "ego_position_xy_m": [_finite(position.x), _finite(position.y)],
            "ego_speed_mps": math.hypot(_finite(velocity.x), _finite(velocity.y)),
            "ego_heading_deg": _finite(heading),
            "right_indicator": bool(state & carla.VehicleLightState.RightBlinker),
            "native_actor_id": actor.id}
    if waypoint is not None:
        row["ego_road_id"] = waypoint.road_id
        row["ego_lane_id"] = waypoint.lane_id
    return row


def validate_plan(plan):
    if not isinstance(plan, dict) or plan.get("rate_hz") != RATE_HZ or not 5 <= plan.get("duration_s", 0) <= 120:
        raise ValueError("Pinned bounded Native camera plan required")
    cameras = plan.get("cameras")
    if not isinstance(cameras, list) or tuple(row.get("name") for row in cameras) != CAMERAS:
        raise ValueError("Four named original source cameras required")
    for row in cameras:
        if (row.get("width"), row.get("height")) != SIZES[row["name"]]:
            raise ValueError("Original source-camera dimensions differ")
        pose = row.get("pose")
        if not isinstance(pose, dict) or set(pose) != {"x", "y", "z", "yaw", "pitch"}:
            raise ValueError("Complete Native camera pose required")
        for value in pose.values():
            _finite(value)
        if not 20 <= _finite(row.get("fov_deg")) <= 120:
            raise ValueError("Native camera FOV invalid")
    return {"frames_planned": plan["duration_s"] * RATE_HZ,
            "native_pixels_verified": False}


@contextmanager
def source_cameras(world, ego, carla, plan):
    validate_plan(plan)
    sensors = {}
    try:
        for row in plan["cameras"]:
            blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
            for key, value in (("image_size_x", row["width"]),
                               ("image_size_y", row["height"]),
                               ("fov", row["fov_deg"]), ("sensor_tick", 1/RATE_HZ)):
                blueprint.set_attribute(key, str(value))
            pose = row["pose"]
            transform = carla.Transform(
                carla.Location(x=pose["x"], y=pose["y"], z=pose["z"]),
                carla.Rotation(yaw=pose["yaw"], pitch=pose["pitch"]))
            kwargs = {"attach_to": ego} if row["name"] == "driver_reference" else {}
            sensor = world.spawn_actor(blueprint, transform, **kwargs)
            if sensor is None:
                raise ValueError("Original source camera spawn failed")
            sensors[row["name"]] = sensor
        yield sensors
    finally:
        for sensor in reversed(list(sensors.values())):
            sensor.stop()
            sensor.destroy()


@contextmanager
def ffv1_writer(path, size):
    path = Path(path)
    width, height = size
    if path.exists() or type(width) is not int or type(height) is not int or width <= 0 or height <= 0:
        raise ValueError("Fresh original source video required")
    process = subprocess.Popen(
        ["ffmpeg", "-hide_banner", "-loglevel", "error", "-n", "-f", "rawvideo",
         "-pixel_format", "bgra", "-video_size", f"{width}x{height}",
         "-framerate", str(RATE_HZ), "-i", "pipe:0", "-an", "-c:v", "ffv1",
         "-level", "3", "-pix_fmt", "bgr0", str(path)],
        stdin=subprocess.PIPE, stderr=subprocess.PIPE)
    count = 0
    def write(data):
        nonlocal count
        if len(data) != width * height * 4 or process.poll() is not None:
            raise ValueError("Original BGRA source size or encoder mismatch")
        process.stdin.write(data)
        count += 1
    try:
        yield write
    finally:
        process.stdin.close()
        code = process.wait(timeout=60)
        stderr = process.stderr.read().decode(errors="replace")
        process.stderr.close()
        if code or count == 0:
            raise ValueError("Original source FFV1 encoding failed: " + stderr[-500:])


@contextmanager
def source_recorder(output, sizes=None):
    """Write one frame map and drive history alongside four lossless streams."""
    output = Path(output).resolve()
    repo = next((parent for parent in Path(__file__).resolve().parents
                 if (parent / "batch.json").is_file() and (parent / "runtime.py").is_file()), None)
    if repo is None or not output.is_relative_to(repo / ".runtime-work"):
        raise ValueError("Native source output must be ignored runtime work")
    if not output.is_dir():
        raise ValueError("Materialized Native attempt directory required")
    owned = [output / (camera + ".mkv") for camera in CAMERAS]
    owned += [output / "drive_history.jsonl", output / "video_frames.jsonl"]
    if any(path.exists() for path in owned):
        raise ValueError("Fresh original source paths required")
    sizes = SIZES if sizes is None else sizes
    if set(sizes) != set(CAMERAS):
        raise ValueError("Four original source sizes required")
    with ExitStack() as stack:
        writers = {camera: stack.enter_context(ffv1_writer(output / (camera + ".mkv"), sizes[camera]))
                   for camera in CAMERAS}
        history = stack.enter_context((output / "drive_history.jsonl").open("x", buffering=1))
        frame_map = stack.enter_context((output / "video_frames.jsonl").open("x", buffering=1))
        prior = [-1, -math.inf]
        index = [0]
        def append(snapshot, actor, carla, queues, waypoint=None):
            row = source_row(snapshot, actor, carla, waypoint)
            if row["frame"] <= prior[0] or row["time_s"] <= prior[1]:
                raise ValueError("Nonmonotone Native snapshot")
            if set(queues) != set(CAMERAS):
                raise ValueError("Four original camera queues required")
            pixels = {name: source_camera_frame(queues[name], row["frame"]) for name in CAMERAS}
            if any(len(pixels[name]) != sizes[name][0] * sizes[name][1] * 4 for name in CAMERAS):
                raise ValueError("Original camera dimensions differ from plan")
            for name in CAMERAS:
                writers[name](pixels[name])
            history.write(json.dumps(row, allow_nan=False) + "\n")
            frame_map.write(json.dumps({"video_frame": index[0], "carla_frame": row["frame"],
                                        "time_s": row["time_s"]}, allow_nan=False) + "\n")
            prior[:] = [row["frame"], row["time_s"]]
            index[0] += 1
        yield append

"""Spawn on a source-reviewed Native approach with a measured right-turn route."""

from contextlib import contextmanager
import math

from site_context import validate_site


def _xy(waypoint):
    point = waypoint.transform.location
    x, y = float(point.x), float(point.y)
    if not math.isfinite(x) or not math.isfinite(y):
        raise ValueError("Nonfinite Native waypoint")
    return (x, y)


def verify_route(approach, outgoing, *, required_direct_approach_m=100.0,
                 max_step_m=5.0):
    """Check physical lane geometry; district class remains source-reviewed."""
    if len(approach) < 3 or len(outgoing) < 2:
        raise ValueError("Incomplete approach or departure waypoints")
    first = approach[0]
    if any(wp.road_id != first.road_id or wp.lane_id != first.lane_id for wp in approach):
        raise ValueError("Approach changes lane or road before turn")
    if any(wp.road_id != outgoing[0].road_id or wp.lane_id != outgoing[0].lane_id for wp in outgoing):
        raise ValueError("Departure does not hold the selected lane")
    if outgoing[0].road_id == first.road_id:
        raise ValueError("No observed turning road transition")
    points = [_xy(wp) for wp in approach]
    departure = [_xy(wp) for wp in outgoing]
    steps = [math.dist(a,b) for a,b in zip(points,points[1:])]
    if any(step <= 0 or step > max_step_m for step in steps):
        raise ValueError("Approach waypoint chain is discontinuous")
    length = sum(steps)
    if length < required_direct_approach_m:
        raise ValueError("Direct approach shorter than required observation span")
    incoming = (points[-1][0]-points[-2][0], points[-1][1]-points[-2][1])
    outgoing_vector = (departure[-1][0]-departure[0][0], departure[-1][1]-departure[0][1])
    denominator = math.hypot(*incoming)*math.hypot(*outgoing_vector)
    if denominator == 0:
        raise ValueError("Zero turn vector")
    cross = (incoming[0]*outgoing_vector[1]-incoming[1]*outgoing_vector[0])/denominator
    dot = (incoming[0]*outgoing_vector[0]+incoming[1]*outgoing_vector[1])/denominator
    angle = math.degrees(math.atan2(cross,dot))
    if not -150 < angle < -30:
        raise ValueError("Native route is not a physical right turn")
    return {"approach_road_id":first.road_id,"approach_lane_id":first.lane_id,
            "outgoing_road_id":outgoing[0].road_id,"outgoing_lane_id":outgoing[0].lane_id,
            "direct_approach_m":length,"turn_angle_degrees":angle,
            "approach_waypoints":approach,"outgoing_waypoints":outgoing,
            "approach_points_xy_m":[list(p) for p in points],
            "outgoing_points_xy_m":[list(p) for p in departure]}


@contextmanager
def spawn_right_turn_vehicle(world, blueprint, approach, outgoing,
                             *, required_direct_approach_m=100.0, site_packet=None, site_source_root=None):
    route = verify_route(approach,outgoing,required_direct_approach_m=required_direct_approach_m)
    actor = world.try_spawn_actor(blueprint,approach[0].transform)
    if actor is None:
        raise ValueError("Native vehicle spawn failed")
    try:
        waypoint = world.get_map().get_waypoint(actor.get_location(),project_to_road=False)
        if waypoint is None or (waypoint.road_id,waypoint.lane_id) != (
                route["approach_road_id"],route["approach_lane_id"]):
            raise ValueError("Spawned vehicle outside sourced right-turn approach")
        site = None
        if site_packet is not None:
            if site_source_root is None:
                raise ValueError("Source root required for district/freight-zone packet")
            native_map = world.get_map()
            route["native_map_id"] = getattr(native_map,"name",None)
            site = validate_site(site_packet,route,site_source_root)
        yield {"actor":actor,"route":route,"site_context":site}
    finally:
        actor.destroy()

"""Source-bound district and freight-zone context for a right-turn route.

This checks that authored geometry and review records are internally consistent.
A Native run must still confirm the actual zone, frontage and visible signs.
"""
import hashlib
import math
from pathlib import Path


def _xy(value):
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        raise ValueError('Missing planar site point')
    point = (float(value[0]), float(value[1]))
    if not all(math.isfinite(v) for v in point):
        raise ValueError('Nonfinite site point')
    return point


def _document(root, record, label):
    if not isinstance(record, dict) or not record.get('path') or not record.get('sha256') or not record.get('reviewer') or not record.get('review_method'):
        raise ValueError('Unsourced '+label+' context')
    root = Path(root).resolve()
    path = (root / record['path']).resolve()
    if root not in path.parents or not path.is_file():
        raise ValueError('Missing '+label+' source document')
    digest = hashlib.sha256(path.read_bytes()).hexdigest()
    if digest != record['sha256']:
        raise ValueError('Changed '+label+' source document')
    return digest


def _point_segment_distance(point, a, b):
    vx, vy = b[0]-a[0], b[1]-a[1]
    length2 = vx*vx+vy*vy
    if length2 == 0:
        return math.dist(point,a)
    t = max(0.0,min(1.0,((point[0]-a[0])*vx+(point[1]-a[1])*vy)/length2))
    return math.dist(point,(a[0]+t*vx,a[1]+t*vy))


def _cross(a,b,c):
    return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])


def _intersects(a,b,c,d):
    return (max(min(a[0],b[0]),min(c[0],d[0])) <= min(max(a[0],b[0]),max(c[0],d[0])) and
            max(min(a[1],b[1]),min(c[1],d[1])) <= min(max(a[1],b[1]),max(c[1],d[1])) and
            _cross(a,b,c)*_cross(a,b,d) <= 0 and _cross(c,d,a)*_cross(c,d,b) <= 0)


def _inside(point, polygon):
    x,y=point
    inside=False
    for a,b in zip(polygon,polygon[1:]+polygon[:1]):
        if (a[1]>y)!=(b[1]>y):
            x_edge=a[0]+(y-a[1])*(b[0]-a[0])/(b[1]-a[1])
            if x<x_edge:inside=not inside
    return inside


def route_zone_distance(route_points, polygon):
    route=[_xy(p) for p in route_points]
    zone=[_xy(p) for p in polygon]
    if len(route)<2 or len(zone)<3:
        raise ValueError('Incomplete route or freight-zone geometry')
    area=sum(a[0]*b[1]-b[0]*a[1] for a,b in zip(zone,zone[1:]+zone[:1]))/2
    if abs(area)<0.01:
        raise ValueError('Degenerate freight-zone polygon')
    if any(_inside(p,zone) for p in route):
        return 0.0
    edges=list(zip(zone,zone[1:]+zone[:1]))
    segments=list(zip(route,route[1:]))
    if any(_intersects(a,b,c,d) for a,b in segments for c,d in edges):
        return 0.0
    return min([_point_segment_distance(p,a,b) for p in zone for a,b in segments]+
               [_point_segment_distance(p,a,b) for p in route for a,b in edges])


def validate_site(packet, route, source_root):
    """Bind a reviewed district and designated zone to one realized route."""
    if not isinstance(packet,dict) or not isinstance(route,dict):
        raise ValueError('Missing route/site context')
    district=packet.get('district',{})
    zone=packet.get('freight_loading_zone',{})
    if district.get('type') not in ('business','residential','other'):
        raise ValueError('District class not sourced')
    if not district.get('frontage_facts') or not district.get('building_use_facts'):
        raise ValueError('District frontage/building use omitted')
    district_sha=_document(source_root,district.get('source'),'district')
    if zone.get('designation') != 'freight_loading_zone' or not zone.get('marking_or_sign_evidence'):
        raise ValueError('Freight loading zone designation unverified')
    zone_sha=_document(source_root,zone.get('source'),'freight-zone')
    if zone['source']['path']==district['source']['path']:
        raise ValueError('District and zone need independent source records')
    if zone.get('road_id') != route.get('approach_road_id'):
        raise ValueError('Freight zone belongs to another road')
    if packet.get('native_map_id') != route.get('native_map_id'):
        raise ValueError('Site and Native route map identities differ')
    points=route.get('approach_points_xy_m',[])+route.get('outgoing_points_xy_m',[])
    distance=route_zone_distance(points,zone.get('polygon_xy_m',[]))
    clearance=float(zone.get('minimum_centerline_clearance_m',0))
    adjacency=float(zone.get('maximum_route_distance_m',0))
    if not all(math.isfinite(x) and x>0 for x in (clearance,adjacency)) or clearance>=adjacency:
        raise ValueError('Freight-zone clearance/adjacency contract invalid')
    if distance<clearance or distance>adjacency:
        raise ValueError('Freight zone intrudes on route or is unrelated to it')
    return {'district_type':district['type'],'district_source_sha256':district_sha,
            'freight_zone_source_sha256':zone_sha,'route_zone_distance_m':distance,
            'native_map_id':packet['native_map_id'],
            'physical_acceptance_claimed':False}

"""Request and read back the Native right blinker without clearing other lights."""


def set_right_indicator(vehicle, light_state_type, enabled):
    current = vehicle.get_light_state()
    flag = light_state_type.RightBlinker
    value = current | flag if enabled else current & ~flag
    vehicle.set_light_state(value)
    return {"requested_right_indicator": bool(enabled),
            "readback_right_indicator": bool(vehicle.get_light_state() & flag)}

"""Measure continuous right-indicator path length before a course change.

The business/residential 100-foot and other-area 300-foot boundaries are exact.
The module reports a conservative sampled distance from the first observed On
frame to the authored onset; it never treats weather as an excuse.
"""

import hashlib
import json
import math
from pathlib import Path


FEET_TO_M = 0.3048
REQUIRED = ("drive_history.jsonl", "video_frames.jsonl", "route_context.json")


def _number(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError("Missing finite source measurement")
    return float(value)


def _rows(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def analyze(root: Path) -> dict:
    root = Path(root)
    hashes = {}
    for name in REQUIRED:
        path = root / name
        if not path.is_file():
            raise ValueError("Missing required source: " + name)
        hashes[name] = hashlib.sha256(path.read_bytes()).hexdigest()
    context = json.loads((root / "route_context.json").read_text())
    for key in ("native_map_id", "approach_road_id", "approach_lane_id",
                "outgoing_road_id", "outgoing_lane_id", "native_route_source",
                "district_source", "turn_onset_frame"):
        if context.get(key) is None:
            raise ValueError("Missing sourced route context: " + key)
    district = context.get("district_type")
    if district not in ("business", "residential", "other"):
        raise ValueError("District class not sourced")
    threshold = (100 if district in ("business", "residential") else 300) * FEET_TO_M
    rows, frames = _rows(root / "drive_history.jsonl"), _rows(root / "video_frames.jsonl")
    if len(rows) < 3 or len(rows) != len(frames):
        raise ValueError("Incomplete drive/frame history")
    prior = (-1, -math.inf)
    path = 0.0
    previous_xy = None
    signal_start_path = None
    onset = None
    speeds = []
    seen_off_before_on = False
    prior_indicator = None
    for i, (row, frame) in enumerate(zip(rows, frames)):
        fid, time = row.get("frame"), _number(row.get("time_s"))
        if type(fid) is not int or fid <= prior[0] or time <= prior[1]:
            raise ValueError("Nonmonotone original drive history")
        prior = (fid, time)
        if frame.get("video_frame") != i or frame.get("carla_frame") != fid or frame.get("time_s") != time:
            raise ValueError("Original video frame join failed")
        xy = row.get("ego_position_xy_m")
        if not isinstance(xy, list) or len(xy) != 2:
            raise ValueError("Missing ego path point")
        xy = (_number(xy[0]), _number(xy[1]))
        if previous_xy is not None:
            path += math.dist(xy, previous_xy)
        previous_xy = xy
        indicator = row.get("right_indicator")
        if type(indicator) is not bool:
            raise ValueError("Missing measured right indicator")
        if indicator and prior_indicator is False:
            seen_off_before_on = True
            signal_start_path = path
        if not indicator:
            signal_start_path = None
        prior_indicator = indicator
        speeds.append(_number(row.get("ego_speed_mps")))
        if fid == context["turn_onset_frame"]:
            if not seen_off_before_on or signal_start_path is None or not indicator:
                raise ValueError("No fully observed continuous pre-turn right signal")
            onset = {"frame": fid, "time_s": time, "path_length_m": path,
                     "continuous_right_signal_distance_m": path - signal_start_path,
                     "ego_position_xy_m": list(xy)}
            break
    if onset is None:
        raise ValueError("Turn onset absent from original trace")
    return {"format": "worker-continuous-right-turn-signal-distance", "sources": hashes,
            "district_type": district, "required_distance_m": threshold,
            "turn_onset": onset, "observed_continuous_distance_meets_boundary":
                onset["continuous_right_signal_distance_m"] >= threshold - 1e-9,
            "approach_speed_samples_mps": speeds,
            "route_turn_direction_judgment": "unresolved until Native route geometry is reviewed",
            "weather_exception": "none in NRS 484B.413(2)"}
